import type { Attachment } from 'svelte/attachments';

/** Where in the key the press landed, in −1…1 from the centre. */
export type PressOrigin = { x: number; y: number };

export type PressDepthOptions = {
	/**
	 * Blocks the gesture. Pass the options as a getter — `() => ({ disabled })` — for the
	 * value to stay live, which is what releases a press already in flight.
	 */
	disabled?: boolean;
	onPressStart?: () => void;
	onPressEnd?: () => void;
};

/**
 * The press gesture on its own, for drawing your own surface.
 *
 * Construct it during component initialisation — it owns effects. The press is tracked
 * on the window rather than the element, so a pointer that leaves mid-hold lifts the key
 * and one that comes back presses it again, which is what the browser's own click
 * suppression does.
 */
export class PressDepthState {
	#read: () => PressDepthOptions;

	#pressed = $state(false);
	#tracking = $state(false);
	#origin = $state<PressOrigin | null>(null);

	#node: HTMLElement | null = null;
	#pointer: number | null = null;
	#down = false;

	constructor(options: PressDepthOptions | (() => PressDepthOptions) = {}) {
		this.#read = typeof options === 'function' ? options : () => options;

		/**
		 * A press interrupted by a scroll, a tab switch, a window blur or a pointer that
		 * never reports its release has to come back up. Nothing here stays down because
		 * an event went missing.
		 */
		$effect(() => {
			if (!this.#tracking) return;

			const contains = (event: PointerEvent) => {
				if (!this.#node) return false;
				const r = this.#node.getBoundingClientRect();
				return (
					event.clientX >= r.left &&
					event.clientX <= r.right &&
					event.clientY >= r.top &&
					event.clientY <= r.bottom
				);
			};

			const move = (event: PointerEvent) => {
				if (event.pointerId !== this.#pointer) return;
				this.#setDown(contains(event));
			};
			const lift = (event: PointerEvent) => {
				if (event.pointerId !== this.#pointer) return;
				this.#stop();
			};
			const bail = () => this.#stop();
			const hidden = () => {
				if (document.hidden) this.#stop();
			};

			window.addEventListener('pointermove', move);
			window.addEventListener('pointerup', lift);
			window.addEventListener('pointercancel', lift);
			window.addEventListener('blur', bail);
			document.addEventListener('visibilitychange', hidden);

			return () => {
				window.removeEventListener('pointermove', move);
				window.removeEventListener('pointerup', lift);
				window.removeEventListener('pointercancel', lift);
				window.removeEventListener('blur', bail);
				document.removeEventListener('visibilitychange', hidden);
			};
		});

		$effect(() => {
			if (this.#read().disabled) this.#stop();
		});
	}

	get pressed() {
		return this.#pressed;
	}

	get origin() {
		return this.#origin;
	}

	#setDown(next: boolean) {
		if (this.#down === next) return;
		this.#down = next;
		this.#pressed = next;
		if (next) this.#read().onPressStart?.();
		else this.#read().onPressEnd?.();
	}

	#stop() {
		this.#pointer = null;
		this.#tracking = false;
		this.#origin = null;
		this.#setDown(false);
	}

	/** `{@attach …}` on the element being pressed — it is the hit box. */
	attach: Attachment<HTMLElement> = (element) => {
		this.#node = element;
		return () => {
			this.#node = null;
		};
	};

	/** spread onto the same element */
	handlers = {
		onpointerdown: (event: PointerEvent) => {
			if (this.#read().disabled) return;
			if (event.pointerType === 'mouse' && event.button !== 0) return;

			const target = event.currentTarget;
			const box = this.#node ?? (target instanceof HTMLElement ? target : null);
			if (box) {
				const r = box.getBoundingClientRect();
				this.#origin = {
					x: clamp(((event.clientX - r.left) / r.width) * 2 - 1),
					y: clamp(((event.clientY - r.top) / r.height) * 2 - 1)
				};
			}

			this.#pointer = event.pointerId;
			this.#tracking = true;
			this.#setDown(true);
		},
		/** Auto-repeat is ignored, so a held Enter presses once. */
		onkeydown: (event: KeyboardEvent) => {
			if (this.#read().disabled || event.repeat) return;
			if (event.key === ' ' || event.key === 'Enter') this.#setDown(true);
		},
		onkeyup: (event: KeyboardEvent) => {
			if (event.key === ' ' || event.key === 'Enter' || event.key === 'Escape') {
				this.#setDown(false);
			}
		},
		onblur: () => this.#stop()
	};
}

function clamp(n: number) {
	return Math.max(-1, Math.min(1, n));
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merge class values, resolving Tailwind conflicts so the last one wins.
 *
 * This is what makes the `class` prop on every component behave the way the
 * registry documents it: "appended last to the root, so width and spacing are
 * the caller's". Plain concatenation would leave both `p-2` and the caller's
 * `p-4` in the list and let source order in the stylesheet decide; `twMerge`
 * drops the loser outright.
 *
 * Design-language classes from `layout.css` (`mat-panel`, `press`, `tnum`, …)
 * are not utilities, so `twMerge` passes them through untouched.
 */
export function cn(...inputs: ClassValue[]): string {
	return twMerge(clsx(inputs));
}
